1	//! A warm checker that answers for the components a session asks about, one request at a time.
2	//!
3	//! The one-shot [`crate::resolve`] roots a single program at every component's file. A Storybook session asks about
4	//! one component per story, so this keeps one `tsc --api` process alive, starts it on the first request, and roots a
5	//! small program at just the requested files: the checker loads what those files import, not the project.
6	//!
7	//! The process runs on its own thread with its own runtime, so a caller on any thread (a NAPI worker, a rayon task)
8	//! never nests runtimes and can bound how long it waits. A failure to start or a crash yields an outcome with no
9	//! components and one diagnostic, never an error; after [`MAX_RESTARTS`] crashes the checker stays down.
10	
11	use std::sync::atomic::{AtomicU32, Ordering};
12	use std::sync::{Arc, mpsc};
13	use std::thread::JoinHandle;
14	use std::time::Duration;
15	
16	use caliper_docgen_core::types::semantic::{SemanticOutcome, SemanticProvider, SemanticTarget};
17	use caliper_docgen_tsc_client::Supervisor;
18	use camino::Utf8PathBuf;
19	use tokio::sync::mpsc::{UnboundedReceiver, UnboundedSender, unbounded_channel};
20	
21	use crate::rpc::Rpc;
22	use crate::{SUPPORTED_VERSIONS, SemanticRequest, answer_with, supervisor_config};
23	
24	/// Crashes the checker may have before it stays down for the session.
25	const MAX_RESTARTS: u32 = 3;
26	
27	/// Programs one `tsc` process builds before it is replaced. Its memory grows with every program it has loaded
28	/// (measured: antd reached 600 MiB after 50 single-component programs), and a fresh process costs 30 to 70 ms.
29	const MAX_REQUESTS_PER_PROCESS: u32 = 64;
30	
31	/// Resident memory, in MiB, past which a `tsc` process is replaced between requests. Measured single-component programs
32	/// peak at 157 to 612 MiB (antd the highest); a process past this has loaded more than a story session needs.
33	const DEFAULT_MAX_RSS_MIB: u64 = 768;
34	
35	/// How many requests pass between memory checks: each reads the process table, which costs a few milliseconds.
36	const RSS_CHECK_EVERY: u32 = 4;
37	
38	/// How long dropping a checker waits, by default, for its worker to finish a request and stop `tsc`, before leaving the
39	/// worker to finish on its own. Closing a session must not wait for a 60 s request.
40	const DEFAULT_SHUTDOWN_WAIT: Duration = Duration::from_secs(5);
41	
42	/// How a warm [`OnDemand`] checker starts and is kept: where to find `tsc`, how long to wait on it, and when to replace
43	/// its process.
44	#[derive(Debug, Clone)]
45	pub struct OnDemandConfig {
46	    /// Where `tsc` finds `node_modules`; its `--cwd`, and where the search for `typescript` starts.
47	    pub project_root: Utf8PathBuf,
48	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
49	    pub tsconfig: Option<Utf8PathBuf>,
50	    /// An explicit `tsc` binary, instead of `node_modules/typescript/bin/tsc` above `project_root`.
51	    pub tsc_path: Option<Utf8PathBuf>,
52	    /// Bound on each request to the checker, and on its start-up handshake.
53	    pub request_timeout: Duration,
54	    /// The `typescript` versions the checker may report; one that is not among them is a start-up failure.
55	    pub expected_versions: &'static [&'static str],
56	    /// Resident memory of the `tsc` process, in MiB, past which it is replaced after a request. A request that needs
57	    /// more finishes first: the bound is between requests, not inside one.
58	    pub max_rss_mib: u64,
59	    /// How long dropping the checker waits for a request in progress before it lets the worker finish alone.
60	    pub shutdown_wait: Duration,
61	    /// Environment for the `tsc` process; the tests use it to pick a replay scenario.
62	    pub extra_env: Vec<(String, String)>,
63	}
64	
65	impl OnDemandConfig {
66	    /// A configuration for `project_root` with a 60 second request timeout, the supported versions, a 768 MiB memory
67	    /// bound, a 5 second shutdown wait, and no explicit tsconfig or `tsc` path.
68	    pub fn new(project_root: Utf8PathBuf) -> Self {
69	        Self {
70	            project_root,
71	            tsconfig: None,
72	            tsc_path: None,
73	            request_timeout: Duration::from_secs(60),
74	            expected_versions: SUPPORTED_VERSIONS,
75	            max_rss_mib: DEFAULT_MAX_RSS_MIB,
76	            shutdown_wait: DEFAULT_SHUTDOWN_WAIT,
77	            extra_env: Vec::new(),
78	        }
79	    }
80	}
81	
82	/// The resident memory of a process in MiB: `/proc` where it exists, else `ps`. `None` when neither answers.
83	fn resident_mib(pid: u32) -> Option<u64> {
84	    let kib = match std::fs::read_to_string(format!("/proc/{pid}/status")) {
85	        Ok(status) => status
86	            .lines()
87	            .find_map(|line| line.strip_prefix("VmRSS:"))?
88	            .split_whitespace()
89	            .next()?
90	            .parse::<u64>()
91	            .ok()?,
92	        Err(_) => {
93	            let output = std::process::Command::new("ps").args(["-o", "rss=", "-p", &pid.to_string()]).output().ok()?;
94	            String::from_utf8_lossy(&output.stdout).trim().parse::<u64>().ok()?
95	        }
96	    };
97	    Some(kib / 1024)
98	}
99	
100	/// How often a warm checker's process was replaced on purpose, by cause (crashes are not counted).
101	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
102	pub struct Recycles {
103	    /// Replaced after building the most programs one process is allowed.
104	    pub worn: u32,
105	    /// Replaced after its resident memory passed [`OnDemandConfig::max_rss_mib`].
106	    pub bloated: u32,
107	}
108	
109	/// What the worker thread reports about the process, for the type that owns the thread to read.
110	#[derive(Default)]
111	struct Gauges {
112	    worn: AtomicU32,
113	    bloated: AtomicU32,
114	    /// The process that answered last; 0 before the first answer.
115	    process: AtomicU32,
116	}
117	
118	enum Job {
119	    /// Start the checker now instead of at the first request.
120	    Warm,
121	    Answer {
122	        targets: Vec<SemanticTarget>,
123	        reply: mpsc::SyncSender<SemanticOutcome>,
124	    },
125	}
126	
127	/// A warm `tsc` that answers for the components it is asked about. Dropping it stops the process.
128	pub struct OnDemand {
129	    jobs: Option<UnboundedSender<Job>>,
130	    thread: Option<JoinHandle<()>>,
131	    /// Receives once when the worker has stopped `tsc` and is about to exit.
132	    stopped: std::sync::Mutex<Option<mpsc::Receiver<()>>>,
133	    shutdown_wait: Duration,
134	    gauges: Arc<Gauges>,
135	}
136	
137	impl OnDemand {
138	    /// Starts the worker thread. The `tsc` process itself starts on the first request, or on [`OnDemand::warm_up`].
139	    pub fn new(config: OnDemandConfig) -> Self {
140	        let shutdown_wait = config.shutdown_wait;
141	        let (jobs, queue) = unbounded_channel();
142	        let (stopped_tx, stopped) = mpsc::channel();
143	        let gauges = Arc::new(Gauges::default());
144	        let worker_gauges = Arc::clone(&gauges);
145	        let thread = std::thread::Builder::new()
146	            .name("caliper-tsc".to_string())
147	            .spawn(move || {
148	                worker(config, queue, worker_gauges);
149	                stopped_tx.send(()).ok();
150	            })
151	            .ok();
152	        Self {
153	            jobs: thread.as_ref().map(|_| jobs),
154	            thread,
155	            stopped: std::sync::Mutex::new(Some(stopped)),
156	            shutdown_wait,
157	            gauges,
158	        }
159	    }
160	
161	    /// How many times the process has been replaced so far, by cause. A replacement happens after the reply it
162	    /// follows, so read this after the next request to see the last one.
163	    pub fn recycles(&self) -> Recycles {
164	        Recycles {
165	            worn: self.gauges.worn.load(Ordering::Relaxed),
166	            bloated: self.gauges.bloated.load(Ordering::Relaxed),
167	        }
168	    }
169	
170	    /// The operating system's id of the `tsc` process that answered the last request, `None` before the first one.
171	    /// Read after a reply, it is the process that built that answer.
172	    pub fn process_id(&self) -> Option<u32> {
173	        Some(self.gauges.process.load(Ordering::Relaxed)).filter(|pid| *pid != 0)
174	    }
175	
176	    /// Starts `tsc` in the background so the first request does not pay for it.
177	    pub fn warm_up(&self) {
178	        if let Some(jobs) = &self.jobs {
179	            jobs.send(Job::Warm).ok();
180	        }
181	    }
182	}
183	
184	impl SemanticProvider for OnDemand {
185	    fn request(&self, targets: Vec<SemanticTarget>) -> mpsc::Receiver<SemanticOutcome> {
186	        let (reply, receiver) = mpsc::sync_channel(1);
187	        match &self.jobs {
188	            Some(jobs) => {
189	                if let Err(refused) = jobs.send(Job::Answer { targets, reply })
190	                    && let Job::Answer { reply, .. } = refused.0
191	                {
192	                    reply.send(SemanticOutcome::unavailable("the checker thread has stopped")).ok();
193	                }
194	            }
195	            None => {
196	                reply.send(SemanticOutcome::unavailable("could not start the checker thread")).ok();
197	            }
198	        }
199	        receiver
200	    }
201	}
202	
203	impl Drop for OnDemand {
204	    fn drop(&mut self) {
205	        // Closing the queue ends the worker loop, which shuts `tsc` down before the thread exits. A worker still inside
206	        // a long request is left to finish it: `tsc` stops when it does, or with this process.
207	        self.jobs.take();
208	        let receiver = self.stopped.get_mut().ok().and_then(Option::take);
209	        let stopped = receiver.is_none_or(|receiver| receiver.recv_timeout(self.shutdown_wait).is_ok());
210	        if let Some(thread) = self.thread.take()
211	            && stopped
212	        {
213	            thread.join().ok();
214	        }
215	    }
216	}
217	
218	fn worker(config: OnDemandConfig, mut queue: UnboundedReceiver<Job>, gauges: Arc<Gauges>) {
219	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
220	        Ok(runtime) => runtime,
221	        Err(error) => {
222	            let reason = format!("could not start an async runtime: {error}");
223	            while let Some(job) = queue.blocking_recv() {
224	                if let Job::Answer { reply, .. } = job {
225	                    reply.send(SemanticOutcome::unavailable(reason.clone())).ok();
226	                }
227	            }
228	            return;
229	        }
230	    };
231	    runtime.block_on(async move {
232	        let mut checker = Checker { gauges, ..Checker::default() };
233	        while let Some(job) = queue.recv().await {
234	            match job {
235	                Job::Warm => {
236	                    checker.ensure(&config).await.ok();
237	                }
238	                Job::Answer { targets, reply } => {
239	                    reply.send(checker.answer(&config, targets).await).ok();
240	                    // After the reply, so the caller never waits for the memory check or the replacement.
241	                    checker.maintain(&config).await;
242	                }
243	            }
244	        }
245	        if let Some(supervisor) = checker.supervisor.take() {
246	            supervisor.shutdown().await.ok();
247	        }
248	    });
249	}
250	
251	#[derive(Default)]
252	struct Checker {
253	    supervisor: Option<Supervisor>,
254	    /// Compiler options read once from the tsconfig for the running process.
255	    options: Option<serde_json::Value>,
256	    restarts: u32,
257	    /// Requests the running process has answered.
258	    served: u32,
259	    /// Why the checker cannot be used for the rest of the session.
260	    down: Option<String>,
261	    gauges: Arc<Gauges>,
262	}
263	
264	impl Checker {
265	    async fn ensure(&mut self, config: &OnDemandConfig) -> Result<(), String> {
266	        if let Some(reason) = &self.down {
267	            return Err(reason.clone());
268	        }
269	        if self.supervisor.as_ref().is_some_and(|supervisor| !supervisor.is_alive()) {
270	            if let Some(dead) = self.supervisor.take() {
271	                dead.shutdown().await.ok();
272	            }
273	            self.options = None;
274	            self.restarts += 1;
275	            if self.restarts > MAX_RESTARTS {
276	                return Err(self.stay_down("the checker kept crashing".to_string()));
277	            }
278	        }
279	        if self.supervisor.is_none() {
280	            let request = SemanticRequest {
281	                project_root: config.project_root.clone(),
282	                tsconfig: config.tsconfig.clone(),
283	                tsc_path: config.tsc_path.clone(),
284	                targets: Vec::new(),
285	                request_timeout: config.request_timeout,
286	                expected_versions: config.expected_versions,
287	                record_to: None,
288	                extra_env: config.extra_env.clone(),
289	                reverse_queries: false,
290	                prepared_options: None,
291	            };
292	            let started = supervisor_config(&request).map_err(|reason| self.stay_down(reason))?;
293	            let supervisor = match Supervisor::spawn(started).await {
294	                Ok(supervisor) => supervisor,
295	                Err(error) => return Err(self.stay_down(error.to_string())),
296	            };
297	            // Initialize the session and read the compiler options once; every request after builds only its program.
298	            let tsconfig = config.tsconfig.as_ref().map(|path| path.as_str());
299	            match Rpc::prepare(&supervisor.client(), config.request_timeout, tsconfig).await {
300	                Ok(options) => self.options = Some(options),
301	                Err(error) => {
302	                    supervisor.shutdown().await.ok();
303	                    return Err(self.stay_down(format!("the checker did not initialize: {error}")));
304	                }
305	            }
306	            self.supervisor = Some(supervisor);
307	        }
308	        Ok(())
309	    }
310	
311	    fn stay_down(&mut self, reason: String) -> String {
312	        self.down = Some(reason.clone());
313	        reason
314	    }
315	
316	    async fn answer(&mut self, config: &OnDemandConfig, targets: Vec<SemanticTarget>) -> SemanticOutcome {
317	        if let Err(reason) = self.ensure(config).await {
318	            return SemanticOutcome::unavailable(reason);
319	        }
320	        let Some(supervisor) = self.supervisor.as_ref() else {
321	            return SemanticOutcome::unavailable("the checker is not running");
322	        };
323	        let mut request = SemanticRequest::new(config.project_root.clone(), targets);
324	        request.tsconfig = config.tsconfig.clone();
325	        request.tsc_path = config.tsc_path.clone();
326	        request.request_timeout = config.request_timeout;
327	        request.expected_versions = config.expected_versions;
328	        request.extra_env.clone_from(&config.extra_env);
329	        request.prepared_options.clone_from(&self.options);
330	        let outcome = answer_with(supervisor, &request).await;
331	        self.gauges.process.store(supervisor.process_id().unwrap_or(0), Ordering::Relaxed);
332	        self.served += 1;
333	        outcome
334	    }
335	
336	    /// Replaces the process when it has built enough programs or grown past the memory bound. A planned replacement,
337	    /// not a crash: the next request starts a fresh process.
338	    async fn maintain(&mut self, config: &OnDemandConfig) {
339	        let Some(supervisor) = self.supervisor.as_ref() else { return };
340	        let worn = self.served >= MAX_REQUESTS_PER_PROCESS;
341	        let resident = (!worn && self.served.is_multiple_of(RSS_CHECK_EVERY))
342	            .then(|| supervisor.process_id().and_then(resident_mib))
343	            .flatten();
344	        let bloated = resident.is_some_and(|mib| mib > config.max_rss_mib);
345	        if worn || bloated {
346	            let (count, cause) = if worn { (&self.gauges.worn, "worn") } else { (&self.gauges.bloated, "bloated") };
347	            count.fetch_add(1, Ordering::Relaxed);
348	            tracing::debug!(cause, served = self.served, resident_mib = ?resident, "replacing the checker process");
349	            if let Some(old) = self.supervisor.take() {
350	                old.shutdown().await.ok();
351	            }
352	            self.options = None;
353	            self.served = 0;
354	        }
355	    }
356	}
357	
358	#[cfg(test)]
359	mod tests {
360	    use super::resident_mib;
361	
362	    #[test]
363	    fn a_running_process_has_resident_memory() {
364	        let mib = resident_mib(std::process::id()).expect("this process is listed");
365	        assert!((1..16_384).contains(&mib), "{mib} MiB");
366	    }
367	
368	    #[test]
369	    fn a_process_that_does_not_exist_has_none() {
370	        assert_eq!(resident_mib(u32::MAX - 1), None);
371	    }
372	}
