111	fn determinism(src: &Utf8PathBuf, tsc: &str, components: usize, threads: &[String], runs: usize) -> bool {
112	    let (probe, _checker) = open(src, tsc, Vec::new(), None);
113	    let mut keys = probe.component_keys();
114	    keys.retain(|key| key != "GateEdited");
115	    keys.sort();
116	    let step = (keys.len() / components.max(1)).max(1);
117	    let keys: Vec<String> = keys.into_iter().step_by(step).take(components).collect();
118	    drop(probe);
119	    let mut reference: Option<String> = None;
120	    let (mut ok, mut variants) = (true, Vec::new());
121	    for count in threads {
122	        for run in 0..runs {
123	            let env = vec![("RAYON_NUM_THREADS".to_string(), count.clone())];
124	            let (session, checker) = open(src, tsc, env, None);
125	            let mut order = keys.clone();
126	            if run % 2 == 1 {
