142	            }
143	            text.sort();
144	            let bytes = text.iter().map(|(key, body)| format!("{key}\n{body}\n")).collect::<String>();
145	            let same = reference.get_or_insert_with(|| bytes.clone()) == &bytes;
146	            // A component the checker declines keeps its structural answer; that is deterministic too, and is listed.
147	            ok &= same;
148	            structural.sort();
149	            variants.push(format!(
150	                "{{\"threads\":{count},\"run\":{run},\"reversed\":{},\"bytes\":{},\"answeredByChecker\":{},\"structuralOnly\":{structural:?},\"maxProcessThreads\":{most_threads},\"equalsFirst\":{same}}}",
151	                run % 2 == 1,
152	                bytes.len(),
153	                order.len() - structural.len()
154	            ));
155	        }
156	    }
157	    println!(
158	        "{{\"gate\":\"determinism\",\"components\":{},\"variants\":[{}],\"ok\":{ok}}}",
159	        keys.len(),
160	        variants.join(",")
161	    );
