165	/// ADR 0026 S4: how long a story waits for the checker's answer through the Rust client. Each run opens a fresh session
166	/// as the addon does (the checker started in the background at creation), waits until that process is up, then asks for
167	/// `key` once and times the whole answer: the structural pass and the checker's program and conversion for the
168	/// component. Passes when every answer is the checker's and the median is at most `budget_ms`, the addon's default
169	/// `semanticWaitMs`.
170	fn first_answer(src: &Utf8PathBuf, tsc: &str, key: &str, runs: usize, budget_ms: u128) -> bool {
171	    let (mut start, mut first, mut structural, mut answered) = (Vec::new(), Vec::new(), Vec::new(), 0);
172	    for _ in 0..runs.max(1) {
173	        let plain = WatchSession::lazy(PipelineOptions {
174	            src_dirs: vec![src.clone()],
175	            load_dependencies: true,
176	            collapse_inherited_props: CollapseInheritedProps::None,
177	            ..PipelineOptions::default()
178	        });
179	        drop(plain.initialize());
180	        let began = Instant::now();
181	        drop(plain.component(key).expect("the key is a component"));
182	        structural.push(began.elapsed().as_millis());
183	
184	        let (session, checker) = open(src, tsc, Vec::new(), None);
185	        let began = Instant::now();
186	        checker.warm_up();
187	        // Queued behind the warm-up, an empty request returns once the process is up and initialized.
188	        drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
189	        start.push(began.elapsed().as_millis());
190	        let began = Instant::now();
191	        let answer = session.component(key).expect("the key is a component");
192	        first.push(began.elapsed().as_millis());
193	        answered += usize::from(by_checker(&answer));
194	    }
195	    let median = |values: &mut Vec<u128>| {
196	        values.sort_unstable();
197	        values[values.len() / 2]
198	    };
199	    let (start_ms, first_ms, structural_ms) = (median(&mut start), median(&mut first), median(&mut structural));
200	    let ok = answered == first.len() && first_ms <= budget_ms;
201	    println!(
202	        "{{\"gate\":\"first-answer\",\"component\":{key:?},\"runs\":{},\"answeredByChecker\":{answered},\"startMs\":{start_ms},\"structuralMs\":{structural_ms},\"firstAnswerMs\":{first_ms},\"firstAnswerEachMs\":{first:?},\"budgetMs\":{budget_ms},\"ok\":{ok}}}",
203	        first.len(),
204	    );
205	    ok
206	}
207	
208	fn main() {
209	    let args: Vec<String> = std::env::args().collect();
210	    let src = Utf8PathBuf::from(arg(&args, "--src").expect("--src"));
211	    let src = Utf8PathBuf::from_path_buf(std::fs::canonicalize(src).unwrap()).unwrap();
212	    let tsc = arg(&args, "--tsc").expect("--tsc");
213	    let number = |name: &str, default: usize| arg(&args, name).map_or(default, |n| n.parse().expect("a number"));
214	    let ok = match args.get(1).map(String::as_str) {
215	        Some("memory") => memory(
216	            &src,
217	            &tsc,
218	            number("--edits", 650),
219	            arg(&args, "--max-rss-mib").map(|n| n.parse().expect("a number")),
220	        ),
221	        Some("determinism") => {
222	            let threads = arg(&args, "--threads").unwrap_or_else(|| "1,2,4".to_string());
223	            determinism(
224	                &src,
225	                &tsc,
226	                number("--components", 150),
227	                &threads.split(',').map(str::to_string).collect::<Vec<_>>(),
228	                number("--runs", 3),
229	            )
230	        }
231	        Some("first-answer") => first_answer(
232	            &src,
233	            &tsc,
234	            &arg(&args, "--component").unwrap_or_else(|| "ChakraButton".to_string()),
235	            number("--runs", 5),
236	            arg(&args, "--budget-ms").map_or(150, |n| n.parse().expect("a number")),
237	        ),
238	        _ => {
239	            eprintln!("usage: gate_harness memory|determinism|first-answer --src DIR --tsc PATH");
240	            false
241	        }
242	    };
243	    std::process::exit(i32::from(!ok));
244	}
