1	#![allow(clippy::unwrap_used, clippy::expect_used, clippy::print_stdout, clippy::print_stderr)]
2	//! The measurable ADR 0026 gates, through the session a Storybook addon runs: a lazy `WatchSession` asking a warm
3	//! `OnDemand` over the project's own `tsc` (`just gate-measure` runs all three).
4	//!
5	//!   gate_harness memory       --src DIR --tsc PATH [--edits 650] [--max-rss-mib N]
6	//!   gate_harness determinism  --src DIR --tsc PATH [--components 150] [--threads 1,2,4] [--runs 3]
7	//!   gate_harness first-answer --src DIR --tsc PATH [--component ChakraButton] [--runs 5] [--budget-ms 150]
8	//!
9	//! `first-answer` (S4) times the first answer for one component in fresh sessions: see [`first_answer`].
10	//! `memory` rewrites one component's file, tells the session, and asks for the component, `--edits` times; it samples the
11	//! checker's PID and resident memory after every answer and prints the recycles, the peak, and whether the last answer
12	//! equals a fresh session's. `determinism` asks a fresh checker for the same components under each `RAYON_NUM_THREADS`
13	//! (tsrs's `--api` has no checker-count flag; see docs/gate-measurements.md), `--runs` times each, alternating the query
14	//! order, and byte-compares every output. Each prints one JSON line and exits 1 on a failed check.
15	use std::collections::BTreeSet;
16	use std::process::Command;
17	use std::sync::Arc;
18	use std::time::{Duration, Instant};
19	
20	use caliper_docgen_core::pipeline::{CollapseInheritedProps, ComponentAnswer, PipelineOptions, WatchSession};
21	use caliper_docgen_core::types::semantic::SemanticProvider;
22	use caliper_docgen_semantic::{OnDemand, OnDemandConfig};
23	use camino::Utf8PathBuf;
24	
25	const CHECKER_NOTE: &str = "resolved by the TypeScript checker";
26	
27	fn arg(args: &[String], name: &str) -> Option<String> {
28	    args.iter().position(|a| a == name).and_then(|at| args.get(at + 1)).cloned()
29	}
30	
31	/// A lazy session with a warm checker, configured as the addon configures it (dependencies loaded, nothing collapsed).
32	fn open(
33	    src: &Utf8PathBuf,
34	    tsc: &str,
35	    env: Vec<(String, String)>,
36	    max_rss_mib: Option<u64>,
37	) -> (WatchSession, Arc<OnDemand>) {
38	    let mut config = OnDemandConfig::new(src.clone());
39	    config.tsconfig = src.ancestors().map(|dir| dir.join("tsconfig.json")).find(|file| file.is_file());
40	    config.tsc_path = Some(Utf8PathBuf::from(tsc));
41	    config.request_timeout = Duration::from_secs(120);
42	    config.extra_env = env;
43	    config.max_rss_mib = max_rss_mib.unwrap_or(config.max_rss_mib);
44	    let checker = Arc::new(OnDemand::new(config));
45	    let options = PipelineOptions {
46	        src_dirs: vec![src.clone()],
47	        load_dependencies: true,
48	        collapse_inherited_props: CollapseInheritedProps::None,
49	        ..PipelineOptions::default()
50	    };
51	    let session = WatchSession::lazy(options).with_semantic(checker.clone(), Duration::from_secs(120));
52	    drop(session.initialize());
53	    (session, checker)
54	}
55	
56	fn by_checker(answer: &ComponentAnswer) -> bool {
57	    answer.diagnostics.iter().any(|d| d.message.contains(CHECKER_NOTE))
58	}
59	
60	/// Resident MiB and thread count of a process, from `ps`; `None` once it has gone.
61	fn process_stats(pid: u32) -> Option<(u64, usize)> {
62	    let ps = |args: &[&str]| {
63	        let out = Command::new("ps").args(args).arg("-p").arg(pid.to_string()).output().ok()?;
64	        out.status.success().then(|| String::from_utf8_lossy(&out.stdout).into_owned())
65	    };
66	    let rss: u64 = ps(&["-o", "rss="])?.trim().parse().ok()?;
67	    Some((rss / 1024, ps(&["-M"])?.lines().count().saturating_sub(1)))
68	}
69	
70	fn edit_source(n: usize) -> String {
71	    format!(
72	        "import type {{ ButtonProps }} from '@chakra-ui/react'\nexport function GateEdited(props: ButtonProps & {{ edit{n}: string }}) {{\n  return null\n}}\n"
73	    )
74	}
75	
76	fn memory(src: &Utf8PathBuf, tsc: &str, edits: usize, max_rss_mib: Option<u64>) -> bool {
77	    let file = src.join("GateEdited.tsx");
78	    std::fs::write(&file, edit_source(0)).unwrap();
79	    let (session, checker) = open(src, tsc, Vec::new(), max_rss_mib);
80	    let (mut processes, mut peak, mut answered, mut stale) = (BTreeSet::new(), 0, 0, 0);
81	    for n in 1..=edits {
82	        std::fs::write(&file, edit_source(n)).unwrap();
83	        session.update_file(&file);
84	        let answer = session.component("GateEdited").expect("GateEdited is a component");
85	        // The answer must be the checker's, for this edit: a structural fallback would measure nothing.
86	        answered += usize::from(by_checker(&answer));
87	        stale += usize::from(!answer.entry.props.contains_key(&format!("edit{n}")));
88	        if let Some(pid) = checker.process_id() {
89	            processes.insert(pid);
90	            peak = peak.max(process_stats(pid).map_or(0, |(mib, _)| mib));
91	        }
92	    }
93	    // A replacement follows the reply it is due after, so one more request settles the counters.
94	    drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
95	    let last = session.component("GateEdited").unwrap();
96	    let (fresh_session, _fresh) = open(src, tsc, Vec::new(), None);
97	    let fresh = fresh_session.component("GateEdited").unwrap();
98	    let recycles = checker.recycles();
99	    let ok = answered == edits && stale == 0 && last == fresh;
100	    println!(
101	        "{{\"gate\":\"memory\",\"edits\":{edits},\"maxRssMib\":{},\"answeredByChecker\":{answered},\"staleAnswers\":{stale},\"processes\":{},\"recycles\":{{\"worn\":{},\"bloated\":{}}},\"peakRssMib\":{peak},\"finalEqualsFresh\":{},\"ok\":{ok}}}",
102	        max_rss_mib.map_or("null".to_string(), |mib| mib.to_string()),
103	        processes.len(),
104	        recycles.worn,
105	        recycles.bloated,
106	        last == fresh,
107	    );
108	    ok
109	}
110	
111	fn determinism(src: &Utf8PathBuf, tsc: &str, components: usize, threads: &[String], runs: usize) -> bool {
112	    let (probe, _checker) = open(src, tsc, Vec::new(), None);
113	    let mut keys = probe.component_keys();
114	    keys.retain(|key| key != "GateEdited");
115	    keys.sort();
116	    let step = (keys.len() / components.max(1)).max(1);
117	    let keys: Vec<String> = keys.into_iter().step_by(step).take(components).collect();
118	    drop(probe);
119	    let mut reference: Option<String> = None;
120	    let (mut ok, mut variants) = (true, Vec::new());
121	    for count in threads {
122	        for run in 0..runs {
123	            let env = vec![("RAYON_NUM_THREADS".to_string(), count.clone())];
124	            let (session, checker) = open(src, tsc, env, None);
125	            let mut order = keys.clone();
126	            if run % 2 == 1 {
127	                order.reverse();
128	            }
129	            let (mut text, mut structural, mut most_threads) = (Vec::new(), Vec::new(), 0);
130	            for key in &order {
131	                let answer = session.component(key).expect("a sampled key is a component");
132	                if !by_checker(&answer) {
133	                    structural.push(key.clone());
134	                }
135	                text.push((
136	                    key.clone(),
137	                    format!("{}\n{:?}", serde_json::to_string(&answer.entry).unwrap(), answer.diagnostics),
138	                ));
139	                if let Some((_, count)) = checker.process_id().and_then(process_stats) {
140	                    most_threads = most_threads.max(count);
141	                }
142	            }
143	            text.sort();
144	            let bytes = text.iter().map(|(key, body)| format!("{key}\n{body}\n")).collect::<String>();
145	            let same = reference.get_or_insert_with(|| bytes.clone()) == &bytes;
146	            // A component the checker declines keeps its structural answer; that is deterministic too, and is listed.
147	            ok &= same;
148	            structural.sort();
149	            variants.push(format!(
150	                "{{\"threads\":{count},\"run\":{run},\"reversed\":{},\"bytes\":{},\"answeredByChecker\":{},\"structuralOnly\":{structural:?},\"maxProcessThreads\":{most_threads},\"equalsFirst\":{same}}}",
151	                run % 2 == 1,
152	                bytes.len(),
153	                order.len() - structural.len()
154	            ));
155	        }
156	    }
157	    println!(
158	        "{{\"gate\":\"determinism\",\"components\":{},\"variants\":[{}],\"ok\":{ok}}}",
159	        keys.len(),
160	        variants.join(",")
161	    );
162	    ok
163	}
164	
165	/// ADR 0026 S4: how long a story waits for the checker's answer through the Rust client. Each run opens a fresh session
166	/// as the addon does (the checker started in the background at creation), waits until that process is up, then asks for
167	/// `key` once and times the whole answer: the structural pass and the checker's program and conversion for the
168	/// component. Passes when every answer is the checker's and the median is at most `budget_ms`, the addon's default
169	/// `semanticWaitMs`.
170	fn first_answer(src: &Utf8PathBuf, tsc: &str, key: &str, runs: usize, budget_ms: u128) -> bool {
171	    let (mut start, mut first, mut structural, mut answered) = (Vec::new(), Vec::new(), Vec::new(), 0);
172	    for _ in 0..runs.max(1) {
173	        let plain = WatchSession::lazy(PipelineOptions {
174	            src_dirs: vec![src.clone()],
175	            load_dependencies: true,
176	            collapse_inherited_props: CollapseInheritedProps::None,
177	            ..PipelineOptions::default()
178	        });
179	        drop(plain.initialize());
180	        let began = Instant::now();
181	        drop(plain.component(key).expect("the key is a component"));
182	        structural.push(began.elapsed().as_millis());
183	
184	        let (session, checker) = open(src, tsc, Vec::new(), None);
185	        let began = Instant::now();
186	        checker.warm_up();
187	        // Queued behind the warm-up, an empty request returns once the process is up and initialized.
188	        drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
189	        start.push(began.elapsed().as_millis());
190	        let began = Instant::now();
191	        let answer = session.component(key).expect("the key is a component");
192	        first.push(began.elapsed().as_millis());
193	        answered += usize::from(by_checker(&answer));
194	    }
195	    let median = |values: &mut Vec<u128>| {
196	        values.sort_unstable();
197	        values[values.len() / 2]
198	    };
199	    let (start_ms, first_ms, structural_ms) = (median(&mut start), median(&mut first), median(&mut structural));
200	    let ok = answered == first.len() && first_ms <= budget_ms;
201	    println!(
202	        "{{\"gate\":\"first-answer\",\"component\":{key:?},\"runs\":{},\"answeredByChecker\":{answered},\"startMs\":{start_ms},\"structuralMs\":{structural_ms},\"firstAnswerMs\":{first_ms},\"firstAnswerEachMs\":{first:?},\"budgetMs\":{budget_ms},\"ok\":{ok}}}",
203	        first.len(),
204	    );
205	    ok
206	}
207	
208	fn main() {
209	    let args: Vec<String> = std::env::args().collect();
210	    let src = Utf8PathBuf::from(arg(&args, "--src").expect("--src"));
211	    let src = Utf8PathBuf::from_path_buf(std::fs::canonicalize(src).unwrap()).unwrap();
212	    let tsc = arg(&args, "--tsc").expect("--tsc");
213	    let number = |name: &str, default: usize| arg(&args, name).map_or(default, |n| n.parse().expect("a number"));
214	    let ok = match args.get(1).map(String::as_str) {
215	        Some("memory") => memory(
216	            &src,
217	            &tsc,
218	            number("--edits", 650),
219	            arg(&args, "--max-rss-mib").map(|n| n.parse().expect("a number")),
220	        ),
221	        Some("determinism") => {
222	            let threads = arg(&args, "--threads").unwrap_or_else(|| "1,2,4".to_string());
223	            determinism(
224	                &src,
225	                &tsc,
226	                number("--components", 150),
227	                &threads.split(',').map(str::to_string).collect::<Vec<_>>(),
228	                number("--runs", 3),
229	            )
230	        }
231	        Some("first-answer") => first_answer(
232	            &src,
233	            &tsc,
234	            &arg(&args, "--component").unwrap_or_else(|| "ChakraButton".to_string()),
235	            number("--runs", 5),
236	            arg(&args, "--budget-ms").map_or(150, |n| n.parse().expect("a number")),
237	        ),
238	        _ => {
239	            eprintln!("usage: gate_harness memory|determinism|first-answer --src DIR --tsc PATH");
240	            false
241	        }
242	    };
243	    std::process::exit(i32::from(!ok));
244	}
