1	//! Experimental TypeScript 7.1 checker backend (`--experimental-semantic-types`).
2	//!
3	//! Spawns `tsc --api` (through `caliper-docgen-tsc-client`), asks it for the props of each component the structural
4	//! pass found, and hands `caliper-docgen-core` a [`SemanticOutcome`] to merge (ADR 0006, ADR 0007). It is always
5	//! compiled in and enabled at run time. Any failure to start or finish (no `tsc`, an unpinned version, a crash, a
6	//! timeout) yields an outcome with no components and one diagnostic, never an error: the structural result is
7	//! complete on its own.
8	//!
9	//! This slice answers function components exported by name or as `default`; a generic one whose first type parameter
10	//! declares a default is read at that default (`instantiate`). Class components, overloaded components and union props
11	//! types keep their structural result and say why.
12	
13	#![deny(missing_docs)]
14	
15	mod component;
16	mod convert;
17	mod instantiate;
18	mod locate;
19	mod on_demand;
20	mod printed;
21	mod rpc;
22	
23	pub use on_demand::{OnDemand, OnDemandConfig, Recycles};
24	
25	use std::sync::Arc;
26	use std::sync::atomic::{AtomicU64, Ordering};
27	use std::time::Duration;
28	
29	use caliper_docgen_core::types::ExtractionOutput;
30	use caliper_docgen_core::types::semantic::{PropInterner, SemanticComponent, SemanticFallback, SemanticOutcome};
31	use caliper_docgen_tsc_client::{Supervisor, SupervisorConfig};
32	use camino::{Utf8Path, Utf8PathBuf};
33	use rustc_hash::FxHashMap;
34	use tokio::sync::Semaphore;
35	use tokio::task::JoinSet;
36	
37	use crate::component::Answer;
38	use crate::convert::Converter;
39	use crate::instantiate::Instantiation;
40	use crate::rpc::{CallError, REQUESTS, Rpc};
41	
42	/// The builds whose protocol this backend was traced against: the `typescript` 7.1 series, from `7.1.0-beta` on, and
43	/// the `tsrs` builds listed exactly (`<tsrs version>-ts<typescript version>`), each only while its TypeScript part is
44	/// in the series above. The protocol has no version handshake, so the package's `package.json` version and the
45	/// initialize call that follows the spawn are the whole check; a build that fails either takes the structural result
46	/// with one warning.
47	pub const SUPPORTED_VERSIONS: &[&str] = &["7.1", "0.23.0-ts7.1.0-beta"];
48	
49	/// How many files are asked about at once. `tsc` answers requests one at a time; this keeps it from idling on round
50	/// trips.
51	const FILES_IN_FLIGHT: usize = 16;
52	
53	/// A component the structural pass found.
54	pub use caliper_docgen_core::types::semantic::SemanticTarget as Target;
55	
56	/// The components of `output`, in output order.
57	pub fn targets_of(output: &ExtractionOutput) -> Vec<Target> {
58	    output
59	        .components
60	        .values()
61	        .map(|entry| Target {
62	            file_path: entry.file_path.clone(),
63	            display_name: entry.display_name.clone(),
64	            exported: entry.exported,
65	            described: entry
66	                .props
67	                .values()
68	                .filter(|prop| !prop.description.is_empty())
69	                .map(|prop| prop.name.clone())
70	                .collect(),
71	            // The whole-project merge leaves `@types/react`'s props to the inheritance layers.
72	            react_wanted: Some(Default::default()),
73	        })
74	        .collect()
75	}
76	
77	/// One whole-project request to the checker: the components to answer for, and how to reach `tsc`. Built with
78	/// [`SemanticRequest::new`] and answered by [`resolve`].
79	#[derive(Debug, Clone)]
80	pub struct SemanticRequest {
81	    /// Where `tsc` finds `node_modules`; its `--cwd`, and where the search for `typescript` starts.
82	    pub project_root: Utf8PathBuf,
83	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
84	    pub tsconfig: Option<Utf8PathBuf>,
85	    /// An explicit `tsc` binary, instead of `node_modules/typescript/bin/tsc` above `project_root`.
86	    pub tsc_path: Option<Utf8PathBuf>,
87	    /// The components to ask about.
88	    pub targets: Vec<Target>,
89	    /// Bound on each request, and on the `tsc` start-up handshake.
90	    pub request_timeout: Duration,
91	    /// The `typescript` versions the checker may report; one that is not among them is a start-up failure.
92	    pub expected_versions: &'static [&'static str],
93	    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
94	    pub record_to: Option<Utf8PathBuf>,
95	    /// Environment for the `tsc` process; the tests use it to pick a replay scenario.
96	    pub extra_env: Vec<(String, String)>,
97	    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
98	    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
99	    pub reverse_queries: bool,
100	    /// Compiler options of a `tsc` session that is already initialized. A warm checker sets this once so a request
101	    /// only builds its program.
102	    pub(crate) prepared_options: Option<serde_json::Value>,
103	}
104	
105	impl SemanticRequest {
106	    /// A request for `targets` under `project_root`, with a 60 second timeout, the supported versions, and no
107	    /// tsconfig or explicit `tsc` path.
108	    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
109	        Self {
110	            project_root,
111	            tsconfig: None,
112	            tsc_path: None,
113	            targets,
114	            request_timeout: Duration::from_secs(60),
115	            expected_versions: SUPPORTED_VERSIONS,
116	            record_to: None,
117	            extra_env: Vec::new(),
118	            reverse_queries: false,
119	            prepared_options: None,
120	        }
121	    }
122	}
123	
124	/// Resolves the request's components with the checker. Blocks; builds its own single-threaded runtime, so it must
125	/// not be called from inside one.
126	pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
127	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
128	        Ok(runtime) => runtime,
129	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
130	    };
131	    runtime.block_on(run(request))
132	}
133	
134	/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
135	/// the checker cannot be asked about.
136	fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
137	    let mut outcome = SemanticOutcome::default();
138	    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
139	    let mut order: Vec<&Utf8Path> = Vec::new();
140	    for target in &request.targets {
141	        if !target.exported {
142	            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
143	            continue;
144	        }
145	        let group = by_file.entry(target.file_path.as_path()).or_default();
146	        if group.is_empty() {
147	            order.push(target.file_path.as_path());
148	        }
149	        group.push(target);
150	    }
151	    (outcome, by_file, order)
152	}
153	
154	fn supervisor_config(request: &SemanticRequest) -> Result<SupervisorConfig, String> {
155	    let tsc_path = locate::find_tsc(&request.project_root, request.tsc_path.as_deref())?;
156	    let mut config = SupervisorConfig::new(tsc_path, request.project_root.clone(), request.expected_versions);
157	    config.handshake_timeout = request.request_timeout;
158	    config.extra_env.clone_from(&request.extra_env);
159	    Ok(config)
160	}
161	
162	async fn run(request: SemanticRequest) -> SemanticOutcome {
163	    if !request.targets.iter().any(|target| target.exported) {
164	        return group_by_file(&request).0;
165	    }
166	    let config = match supervisor_config(&request) {
167	        Ok(config) => config,
168	        Err(reason) => return SemanticOutcome::unavailable(reason),
169	    };
170	    let supervisor = match Supervisor::spawn(config).await {
171	        Ok(supervisor) => supervisor,
172	        Err(error) => return SemanticOutcome::unavailable(error.to_string()),
173	    };
174	    let outcome = answer_with(&supervisor, &request).await;
175	    supervisor.shutdown().await.ok();
176	    outcome
177	}
178	
179	/// Answers the request's targets with a checker that is already running: one program rooted at their files.
180	async fn answer_with(supervisor: &Supervisor, request: &SemanticRequest) -> SemanticOutcome {
181	    let (mut outcome, by_file, order) = group_by_file(request);
182	    if order.is_empty() {
183	        return outcome;
184	    }
185	    let files: Vec<String> = order.iter().map(|file| file.to_string()).collect();
186	    match session(supervisor, request, &files, &by_file, &order).await {
187	        Ok(mut answered) => {
188	            outcome.components.append(&mut answered.components);
189	            outcome.fallbacks.append(&mut answered.fallbacks);
190	            outcome
191	        }
192	        Err(error) => SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
193	    }
194	}
195	
196	async fn session(
197	    supervisor: &Supervisor,
198	    request: &SemanticRequest,
199	    files: &[String],
200	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
201	    order: &[&Utf8Path],
202	) -> Result<SemanticOutcome, CallError> {
203	    let started = std::time::Instant::now();
204	    let opened = match &request.prepared_options {
205	        Some(options) => {
206	            Rpc::open_with(supervisor.client(), request.request_timeout, options, files, request.record_to.is_some())
207	                .await
208	        }
209	        None => {
210	            Rpc::open(
211	                supervisor.client(),
212	                request.request_timeout,
213	                request.tsconfig.as_ref().map(|path| path.as_str()),
214	                files,
215	                request.record_to.is_some(),
216	            )
217	            .await
218	        }
219	    };
220	    let rpc = Arc::new(opened?);
221	    let opened = started.elapsed();
222	    let converter = Converter::new(rpc.clone(), request.reverse_queries);
223	    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
224	    let interner = Arc::new(PropInterner::default());
225	
226	    let mut tasks = JoinSet::new();
227	    for file in order {
228	        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
229	        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
230	        tasks.spawn(async move {
231	            let _permit = limit.acquire().await;
232	            answer_file(&rpc, &converter, &interner, targets).await
233	        });
234	    }
235	
236	    let mut outcome = SemanticOutcome::default();
237	    let mut generic = Vec::new();
238	    let mut failure = None;
239	    while let Some(joined) = tasks.join_next().await {
240	        match joined {
241	            Ok(Ok((mut answered, mut instantiations))) => {
242	                outcome.components.append(&mut answered.components);
243	                outcome.fallbacks.append(&mut answered.fallbacks);
244	                generic.append(&mut instantiations);
245	            }
246	            Ok(Err(error)) => {
247	                failure = Some(error);
248	                tasks.abort_all();
249	            }
250	            // A panic inside a worker must not silently leave its components structural.
251	            Err(joined) if joined.is_panic() => {
252	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
253	                tasks.abort_all();
254	            }
255	            // A cancelled task is one this loop aborted after a failure.
256	            Err(_cancelled) => {}
257	        }
258	    }
259	    if let Some(error) = failure {
260	        return Err(error);
261	    }
262	    if !generic.is_empty() {
263	        let mut instantiated =
264	            instantiate::answer(&rpc, files, &request.project_root, &interner, request.reverse_queries, generic)
265	                .await?;
266	        outcome.components.append(&mut instantiated.components);
267	        outcome.fallbacks.append(&mut instantiated.fallbacks);
268	    }
269	
270	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
271	        && let Ok(json) = serde_json::to_string_pretty(&recording)
272	        && let Err(error) = std::fs::write(path, json)
273	    {
274	        tracing::warn!("could not write the recording to {path}: {error}");
275	    }
276	    tracing::debug!(
277	        requests = ?rpc.calls(),
278	        files = files.len(),
279	        type_memo = ?converter.memo_stats(),
280	        program_ms = opened.as_millis() as u64,
281	        total_ms = started.elapsed().as_millis() as u64,
282	        "semantic backend finished"
283	    );
284	    rpc.release().await;
285	    outcome.components.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
286	    outcome.fallbacks.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
287	    Ok(outcome)
288	}
289	
290	fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
291	    SemanticFallback {
292	        file_path: target.file_path.clone(),
293	        display_name: target.display_name.clone(),
294	        reason: reason.to_string(),
295	    }
296	}
297	
298	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
299	/// generic components come back apart, to be answered from their instantiations once every file is done.
300	async fn answer_file(
301	    rpc: &Rpc,
302	    converter: &Converter,
303	    interner: &PropInterner,
304	    targets: Vec<Target>,
305	) -> Result<(SemanticOutcome, Vec<(Target, Instantiation)>), CallError> {
306	    let mut outcome = SemanticOutcome::default();
307	    let mut generic = Vec::new();
308	    let Some(first) = targets.first() else { return Ok((outcome, generic)) };
309	    let exports = match module_exports(rpc, first.file_path.as_str()).await {
310	        Ok(Some(exports)) => exports,
311	        Ok(None) | Err(CallError::Rejected(_)) => {
312	            outcome
313	                .fallbacks
314	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
315	            return Ok((outcome, generic));
316	        }
317	        Err(fatal) => return Err(fatal),
318	    };
319	
320	    for target in &targets {
321	        let requests = Arc::new(AtomicU64::new(0));
322	        let started = std::time::Instant::now();
323	        let answered =
324	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &exports, target)).await;
325	        tracing::debug!(
326	            component = %target.display_name,
327	            requests = requests.load(Ordering::Relaxed),
328	            ms = started.elapsed().as_millis() as u64,
329	            "semantic component answered"
330	        );
331	        match answered {
332	            Ok(Answer::Props(props)) => outcome.components.push(SemanticComponent {
333	                file_path: target.file_path.clone(),
334	                display_name: target.display_name.clone(),
335	                props,
336	            }),
337	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
338	            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
339	            Err(CallError::Rejected(message)) => {
340	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
341	            }
342	            Err(fatal) => return Err(fatal),
343	        }
344	    }
345	    Ok((outcome, generic))
346	}
347	
348	async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<Vec<rpc::SymbolInfo>>, CallError> {
349	    let Some(module) = rpc.source_file_symbol(file).await? else { return Ok(None) };
350	    Ok(Some(rpc.exports_of_module(&module.reference).await?))
351	}
