1	//! Typed calls over one `tsc --api` session. Wire shapes are the ones the official 7.1 client sends (traced against
2	//! `7.1.0-beta`); a method this module does not name is not used.
3	
4	use std::collections::BTreeMap;
5	use std::sync::{Arc, Mutex};
6	use std::time::Duration;
7	
8	use caliper_docgen_tsc_client::{Client, TscClientError};
9	use serde::Deserialize;
10	use serde::de::DeserializeOwned;
11	use serde_json::value::RawValue;
12	use serde_json::{Value, json};
13	
14	/// Why a call failed, split by whether the rest of the run can go on.
15	#[derive(Debug)]
16	pub(crate) enum CallError {
17	    /// The session is gone or stuck: every later call would fail the same way.
18	    Fatal(String),
19	    /// The checker rejected this one call; other components may still resolve.
20	    Rejected(String),
21	}
22	
23	impl std::fmt::Display for CallError {
24	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
25	        match self {
26	            CallError::Fatal(message) | CallError::Rejected(message) => f.write_str(message),
27	        }
28	    }
29	}
30	
31	fn classify(error: TscClientError) -> CallError {
32	    match error {
33	        TscClientError::RpcError { message, .. } => CallError::Rejected(message),
34	        other => CallError::Fatal(other.to_string()),
35	    }
36	}
37	
38	#[derive(Debug, Clone, Deserialize)]
39	#[serde(rename_all = "camelCase")]
40	pub(crate) struct SymbolInfo {
41	    /// The full reference the checker wants back to name this symbol; opaque to us.
42	    pub reference: Value,
43	    /// The name the source writes: the checker's escaped name with the escaping removed (see
44	    /// [`unescape_leading_underscores`]).
45	    #[serde(deserialize_with = "unescaped_name")]
46	    pub name: String,
47	    pub flags: u64,
48	    #[serde(default)]
49	    pub declarations: Vec<String>,
50	}
51	
52	/// A symbol as another response embeds it: the id, and the node id of the file that owns it. The full symbol is one
53	/// call away (`getSymbolOfType`, `getAliasSymbolOfType`).
54	#[derive(Debug, Clone, PartialEq, Eq, Hash, Deserialize)]
55	pub(crate) struct CompactSymbol {
56	    pub id: u64,
57	    #[serde(default)]
58	    pub file: Option<String>,
59	}
60	
61	/// The checker keeps a symbol's name in an escaped form: a name that starts with two underscores gets a third
62	/// (`escapeLeadingUnderscores`), so that it cannot collide with its own internal names such as `__call`. The source
63	/// writes `__size`, the checker answers `___size`. A name with fewer than three leading underscores is unchanged, and
64	/// so are the internal names, which start with exactly two.
65	pub(crate) fn unescape_leading_underscores(name: &str) -> &str {
66	    if name.starts_with("___") { name.strip_prefix('_').unwrap_or(name) } else { name }
67	}
68	
69	fn unescaped_name<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<String, D::Error> {
70	    let name = String::deserialize(deserializer)?;
71	    Ok(unescape_leading_underscores(&name).to_string())
