298	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
299	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
300	    /// numeric ones.
301	    pub(crate) async fn prepare(
302	        client: &Client,
303	        deadline: Duration,
304	        tsconfig: Option<&str>,
305	    ) -> Result<Value, CallError> {
306	        let rpc = Rpc {
307	            client: client.clone(),
308	            deadline,
309	            snapshot: 0,
310	            project: String::new(),
311	            options: Value::Null,
312	            recording: None,
313	            calls: Arc::default(),
314	        };
315	        rpc.call("initialize", Value::Null).await?;
316	        Ok(match tsconfig {
317	            Some(file) => {
318	                let parsed: Value = decode(&rpc.call("parseConfigFile", json!({ "file": file })).await?)?;
