325	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
326	    pub(crate) async fn open_with(
327	        client: Client,
328	        deadline: Duration,
329	        options: &Value,
330	        root_files: &[String],
331	        record: bool,
332	    ) -> Result<Rpc, CallError> {
333	        let rpc = Rpc {
334	            client,
335	            deadline,
336	            snapshot: 0,
337	            project: String::new(),
338	            options: options.clone(),
339	            recording: record.then(Arc::default),
340	            calls: Arc::default(),
