345	    /// A new snapshot of the same program with `files` added, held in the checker's memory and never written to disk:
346	    /// each is a root file, keyed by its absolute path. The calls on it count, and are recorded, with this one's.
347	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
348	        let rpc = Rpc {
349	            client: self.client.clone(),
350	            deadline: self.deadline,
351	            snapshot: 0,
352	            project: String::new(),
353	            options: self.options.clone(),
354	            recording: self.recording.clone(),
355	            calls: self.calls.clone(),
356	        };
357	        let mut roots = root_files.to_vec();
358	        roots.extend(files.iter().map(|(path, _)| path.clone()));
359	        let layer: serde_json::Map<String, Value> =
360	            files.iter().map(|(path, text)| (path.clone(), Value::String(text.clone()))).collect();
361	        rpc.created(json!({
362	            "fileSystem": { "kind": "layer", "files": layer },
363	            "createPrograms": [{ "rootFiles": roots, "compilerOptions": self.options }],
