396	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
397	    /// expects.
398	    async fn call(&self, method: &str, params: Value) -> Result<Box<RawValue>, CallError> {
399	        if let Ok(mut calls) = self.calls.lock() {
400	            *calls.entry(method.to_string()).or_default() += 1;
401	        }
402	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
403	        let Some(log) = &self.recording else {
404	            return Ok(self.client.request_raw(method, params, self.deadline).await.map_err(classify)?.result);
405	        };
406	        let answer = self.client.request_raw(method, params.clone(), self.deadline).await.map_err(classify)?;
407	        let result: Value = decode(&answer.result)?;
408	        if let Ok(mut log) = log.lock() {
409	            log.push(json!({ "method": method, "params": params, "result": result }));
410	        }
411	        Ok(answer.result)
412	    }
