503	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
504	    /// that may legitimately fail.
505	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Box<RawValue>>, CallError> {
506	        let wanted = requests.len();
507	        let scoped: Vec<Value> = requests
508	            .into_iter()
509	            .map(|(method, mut params)| {
510	                if let Value::Object(map) = &mut params {
511	                    map.insert("snapshot".to_string(), json!(self.snapshot));
512	                    map.insert("project".to_string(), json!(self.project));
513	                }
514	                json!({ "method": method, "params": params })
515	            })
516	            .collect();
517	        let mut answers = Vec::with_capacity(wanted);
518	        let mut token: Option<String> = None;
519	        loop {
520	            let mut params = json!({ "requests": scoped });
521	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
522	                map.insert("continuationToken".to_string(), json!(token));
523	            }
524	            let page: BatchPage = decode(&self.call("batchRequests", params).await?)?;
525	            for response in page.responses {
526	                if let Some(error) = response.error {
527	                    return Err(CallError::Rejected(error));
528	                }
529	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
530	            }
531	            match page.continuation_token {
532	                Some(next) => token = Some(next),
533	                None => break,
534	            }
535	        }
536	        if answers.len() != wanted {
537	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
538	        }
539	        Ok(answers)
540	    }
