567	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Call as u8 })),
568	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Construct as u8 })),
569	            ("getPropertiesOfType", json!({ "type": type_id })),
570	            ("getIndexInfosOfType", json!({ "type": type_id })),
571	        ];
572	        let mut answers = self.batch(requests).await?.into_iter();
573	        let mut next = || answers.next().ok_or_else(|| CallError::Rejected("a short batch".to_string()));
574	        Ok(ObjectMembers {
575	            calls: decode(&next()?)?,
576	            constructs: decode(&next()?)?,
577	            properties: decode(&next()?)?,
578	            indexes: decode(&next()?)?,
579	        })
580	    }
581	
582	    pub(crate) async fn alias_symbol(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
583	        self.scoped("getAliasSymbolOfType", json!({ "objectId": type_id })).await
584	    }
585	
586	    pub(crate) async fn type_to_string(&self, type_id: u64) -> Result<String, CallError> {
587	        self.scoped("typeToString", json!({ "type": type_id })).await
588	    }
589	
590	    /// The type as written inside a type alias declaration, and never cut short: an alias at the top is printed as what
591	    /// it stands for (`(value?: string) => void`, not `Handler`), and a long type is printed to its end.
592	    pub(crate) async fn type_to_string_expanded(&self, type_id: u64) -> Result<String, CallError> {
593	        self.scoped("typeToString", json!({ "type": type_id, "flags": flag::PRINT_EXPANDED })).await
594	    }
595	
596	    pub(crate) async fn documentation(&self, symbol: &Value) -> Result<String, CallError> {
597	        self.scoped("getDocumentationComment", json!({ "symbol": symbol })).await
598	    }
599	}
600	
601	fn default_options() -> Value {
602	    // Numeric enum values: JSX preserve, ESNext modules, bundler resolution, ES2022.
603	    json!({ "jsx": 1, "module": 99, "moduleResolution": 100, "target": 9, "strict": true, "skipLibCheck": true, "noEmit": true })
604	}
605	
606	/// An answer parsed from its text straight into `T`, in one pass.
607	pub(crate) fn decode<T: DeserializeOwned>(answer: &RawValue) -> Result<T, CallError> {
608	    serde_json::from_str(answer.get())
609	        .map_err(|error| CallError::Rejected(format!("unexpected response shape: {error}")))
610	}
611	
612	#[cfg(test)]
613	mod tests {
614	    use super::*;
615	
616	    #[test]
617	    fn a_name_with_three_or_more_leading_underscores_loses_the_one_the_checker_added() {
618	        assert_eq!(unescape_leading_underscores("___size"), "__size");
619	        assert_eq!(unescape_leading_underscores("____triple"), "___triple");
620	        assert_eq!(unescape_leading_underscores("___0"), "__0");
621	    }
622	
623	    #[test]
624	    fn other_names_are_unchanged() {
625	        for name in ["size", "_single", "__call", "__type", "default", "", "a___b"] {
626	            assert_eq!(unescape_leading_underscores(name), name);
627	        }
628	    }
629	
630	    #[test]
631	    fn a_symbol_arrives_with_the_name_the_source_writes() {
632	        let symbol: SymbolInfo =
633	            serde_json::from_value(json!({ "reference": {}, "name": "___size", "flags": 0 })).unwrap();
634	
635	        assert_eq!(symbol.name, "__size");
636	    }
637	}
