1	//! Asking a checker for the component a session was just asked about (ADR 0022).
2	//!
3	//! The structural answer is always computed first and is a complete answer on its own. With a [`SemanticProvider`]
4	//! attached, [`SemanticHook::refine`] asks the checker for exactly that component, waits a bounded time, and merges
5	//! its props over the structural ones. A checker that is slower than the budget leaves the structural answer in
6	//! place, and its late answer is kept for the next request of the same, unedited component.
7	//!
8	//! An answer describes the component's props as the checker read them, which depends on every file the component
9	//! imports, not only its own. So the session drops every answer when any source file changes
10	//! ([`SemanticHook::invalidate`]), and an answer that was still on its way then is not kept.
11	
12	use std::hash::{Hash, Hasher};
13	use std::sync::atomic::{AtomicBool, Ordering};
14	use std::sync::mpsc::{Receiver, RecvTimeoutError};
15	use std::sync::{Arc, Mutex, PoisonError};
16	use std::time::Duration;
17	
18	use rustc_hash::{FxHashMap, FxHasher};
19	
20	use super::ComponentAnswer;
21	use crate::pipeline::HtmlAttributeMode;
22	use crate::react_types::{checker_prop_used, react_props_wanted};
23	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
24	use crate::types::semantic::{
25	    MergedProps, SemanticComponent, SemanticOutcome, SemanticProp, SemanticProvider, SemanticTarget,
26	    merge_semantic_props, unread_diagnostic,
27	};
28	
29	/// What the checker said about one component at one version of its file, and the generation they belong to.
30	#[derive(Default)]
31	struct AnswerCache {
32	    /// Raised by every [`SemanticHook::invalidate`]; an answer asked for under an earlier one is not stored.
33	    generation: u64,
34	    answers: FxHashMap<(String, u64), Option<Arc<SemanticComponent>>>,
35	}
36	
37	type Answers = Mutex<AnswerCache>;
38	
39	pub(crate) struct SemanticHook {
40	    provider: Arc<dyn SemanticProvider>,
41	    /// How long a request waits for the checker before it takes the structural answer.
42	    wait: Duration,
43	    answers: Arc<Answers>,
44	    /// Set once the checker has been reported unavailable, so a session says so once, not per component.
45	    warned: AtomicBool,
46	}
47	
48	impl SemanticHook {
49	    pub(crate) fn new(provider: Arc<dyn SemanticProvider>, wait: Duration) -> Self {
50	        Self { provider, wait, answers: Arc::new(Mutex::new(AnswerCache::default())), warned: AtomicBool::new(false) }
51	    }
52	
53	    /// Forget every answer, and refuse the ones still being waited for: a source file changed, and the checker's
54	    /// props for any component can depend on it. The next request of each component asks the checker again.
55	    pub(crate) fn invalidate(&self) {
56	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
57	        cache.generation += 1;
58	        cache.answers.clear();
59	    }
60	
61	    /// `answer` with the checker's props, when it has them.
62	    pub(crate) fn refine(&self, mut answer: ComponentAnswer, mode: HtmlAttributeMode) -> ComponentAnswer {
63	        let stamp = std::fs::read(&answer.entry.file_path).map(|bytes| {
64	            let mut hasher = FxHasher::default();
65	            bytes.hash(&mut hasher);
66	            hasher.finish()
67	        });
68	        let cache_key = stamp.ok().map(|stamp| (answer.key.clone(), stamp));
69	        let generation = self.generation();
70	
71	        if let Some(cached) = cache_key.as_ref().and_then(|key| self.cached(key)) {
72	            self.apply(&mut answer, cached.as_ref(), mode);
73	            return answer;
74	        }
75	
76	        let target = SemanticTarget {
77	            file_path: answer.entry.file_path.clone(),
78	            display_name: answer.entry.display_name.clone(),
79	            exported: answer.entry.exported,
80	            described: answer
81	                .entry
82	                .props
83	                .values()
84	                .filter(|prop| !prop.description.is_empty())
85	                .map(|prop| prop.name.clone())
86	                .collect(),
87	            react_wanted: react_props_wanted(mode, &answer.entry.props),
88	        };
89	        let receiver = self.provider.request(vec![target]);
90	        match receiver.recv_timeout(self.wait) {
91	            Ok(outcome) => {
92	                let mut reported = Vec::new();
93	                let component = self.take_component(&answer, outcome, &mut reported);
94	                answer.diagnostics.extend(reported);
95	                if let Some(key) = cache_key {
96	                    self.store(key, generation, component.clone());
97	                }
98	                self.apply(&mut answer, component.as_ref(), mode);
99	            }
100	            Err(RecvTimeoutError::Timeout) => {
101	                self.keep_late_answer(receiver, cache_key, generation);
102	                let mut pending = Diagnostic::new(
103	                    DiagnosticSeverity::Info,
104	                    DiagnosticCode::SemanticBackend,
105	                    "the TypeScript checker has not answered yet; the structural props are used, and the checker's \
106	                     replace them on the next request",
