200	/// atomic store, so a reader always sees one complete revision, never parts of two. Writers are serialized; readers
201	/// never wait on them.
202	///
203	/// A lazy session ([`WatchSession::lazy`], ADR 0016) parses and indexes every file and resolves a component only when
204	/// [`WatchSession::component`] asks for it; the rest of this API behaves as for an eager one.
205	pub struct WatchSession {
206	    /// The options the session was created with.
207	    pub options: PipelineOptions,
208	    current: ArcSwapOption<Revision>,
209	    writer: Mutex<Freshness>,
210	    lazy: bool,
211	    semantic: Option<super::semantic_hook::SemanticHook>,
212	}
213	
214	/// The options and mode of a session, not its revision: a revision holds every parsed file and resolved component, so
215	/// printing it would bury the question a `{:?}` asks, which session this is.
216	impl std::fmt::Debug for WatchSession {
217	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
218	        f.debug_struct("WatchSession")
219	            .field("options", &self.options)
220	            .field("lazy", &self.lazy)
221	            .field("revision", &self.revision())
222	            .field("with_semantic", &self.semantic.is_some())
223	            .finish_non_exhaustive()
224	    }
225	}
226	
227	/// What a lazy session has indexed and answered so far.
228	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
229	pub struct LazyStats {
230	    /// The number of the session's current revision.
231	    pub revision: u64,
232	    /// Source files the session holds.
233	    pub files: usize,
234	    /// Components found by parsing.
235	    pub components: usize,
236	    /// Components resolved since the last edit that could change them.
237	    pub resolved: usize,
238	    /// Dependency declaration files loaded so far, for the names resolved components reached.
239	    pub dependency_files: usize,
240	}
241	
242	impl WatchSession {
243	    /// Create an empty WatchSession (call `initialize()` before first use).
244	    pub fn new(options: PipelineOptions) -> Self {
245	        Self {
246	            options,
247	            current: ArcSwapOption::empty(),
248	            writer: Mutex::new(Freshness::cold(SystemTime::UNIX_EPOCH)),
249	            lazy: false,
250	            semantic: None,
251	        }
252	    }
253	
254	    /// Attach a TypeScript checker that is asked for each component a request names (ADR 0022). [`Self::component`]
255	    /// then returns the checker's props when it answers within `wait`, the structural ones otherwise, and the checker's
256	    /// late answer on the next request of the same, unedited component. Without a checker nothing changes.
257	    #[must_use]
258	    pub fn with_semantic(mut self, provider: Arc<dyn SemanticProvider>, wait: Duration) -> Self {
259	        self.semantic = Some(super::semantic_hook::SemanticHook::new(provider, wait));
260	        self
261	    }
262	
263	    /// Create an empty lazy session (call `initialize()` before first use). Its `initialize` parses and indexes every
264	    /// file and returns an output with no components; [`Self::component`] resolves one on request.
265	    ///
266	    /// This is the entry point for a host that links the library and asks about one component at a time (an editor
267	    /// server, a Storybook addon, an MCP server). The session is `Send + Sync`: share it behind an `Arc` and call it
268	    /// from any thread. Answers are owned values with the component's own diagnostics; no parser type crosses the
269	    /// API. Memory is bounded by the project and the dependencies it reaches (ADR 0016).
270	    ///
271	    /// ```
272	    /// use caliper_docgen_core::pipeline::{PipelineOptions, WatchSession};
273	    ///
274	    /// # let dir = tempfile::tempdir()?;
275	    /// # std::fs::write(
276	    /// #     dir.path().join("Button.tsx"),
277	    /// #     "export function Button(props: { /** Shown on the button. */ label: string; size?: 'sm' | 'lg' }) { return null; }",
278	    /// # )?;
279	    /// # let root = camino::Utf8PathBuf::from(dir.path().to_str().unwrap());
280	    /// let session = WatchSession::lazy(PipelineOptions {
281	    ///     src_dirs: vec![root.clone()],
282	    ///     // Resolve the types the project imports from packages, only for the names a request reaches.
283	    ///     load_dependencies: true,
284	    ///     ..Default::default()
285	    /// });
286	    /// let _ = session.initialize(); // parses and indexes every file; resolves nothing
287	    ///
288	    /// // By key, or by file and name when the key isn't known.
289	    /// let button = session.component("Button").expect("Button is a component");
290	    /// assert_eq!(button.entry.props.keys().collect::<Vec<_>>(), ["label", "size"]);
291	    /// assert!(button.diagnostics.is_empty());
292	    /// assert_eq!(session.component_in(&root.join("Button.tsx"), "Button"), Some(button));
293	    ///
294	    /// // As react-docgen-typescript documents it, for Storybook's argTypes.
295	    /// let docgen = session.docgen_info("Button").expect("Button is a component");
296	    /// assert_eq!(docgen["displayName"], "Button");
297	    ///
298	    /// // After an edit, only the components that read the file are resolved again.
299	    /// std::fs::write(root.join("Button.tsx"), "export function Button(props: { label: string }) { return null; }")?;
300	    /// let update = session.update_file(&root.join("Button.tsx"));
301	    /// assert_eq!(update.updated_keys, ["Button"]);
302	    /// assert_eq!(session.component("Button").map(|b| b.entry.props.len()), Some(1));
303	    /// # Ok::<(), Box<dyn std::error::Error>>(())
304	    /// ```
305	    pub fn lazy(options: PipelineOptions) -> Self {
306	        Self { lazy: true, ..Self::new(options) }
307	    }
308	
309	    /// Whether this session resolves components on request rather than all at once.
310	    pub fn is_lazy(&self) -> bool {
311	        self.lazy
312	    }
313	
314	    /// Run a full cold extraction to populate this session.
315	    ///
316	    /// Idempotent — concurrent or repeated calls return the current snapshot without re-running extraction. Use
317	    /// `rebuild` to force a fresh extraction.
318	    pub fn initialize(&self) -> ExtractionOutput {
319	        let mut writer = self.writer.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
320	        if let Some(current) = self.current.load_full() {
321	            return (*current.output).clone();
