57	/// What `stat` reported for a file or directory when it was recorded. `Unknown` never matches a fresh stamp: the path
58	/// may have changed after the revision read it, so it must be applied again.
59	#[derive(Clone, Copy, PartialEq, Eq)]
60	enum Stamp {
61	    Missing,
62	    /// `hash` is set when the modification time was too recent to tell a later edit apart: a hash of a file's
63	    /// contents, or of a directory's entry names.
64	    Present {
65	        modified: SystemTime,
66	        len: u64,
67	        hash: Option<u64>,
68	    },
69	    Unknown,
70	}
71	
72	/// Filesystems that keep modification times to the second, or to a kernel clock tick, give an edit made just after a
73	/// stat the same modification time.
74	const MTIME_GRANULARITY: Duration = Duration::from_secs(2);
75	
76	fn stamp(path: &Utf8Path) -> Stamp {
77	    stamp_like(path, None)
78	}
79	
80	/// A fresh stamp comparable with `recorded`: hashed when `recorded` was, or when the modification time is recent.
81	fn stamp_like(path: &Utf8Path, recorded: Option<&Stamp>) -> Stamp {
82	    let now = SystemTime::now();
83	    let Ok(meta) = std::fs::metadata(path) else { return Stamp::Missing };
84	    let Ok(modified) = meta.modified() else { return Stamp::Unknown };
85	    let hashed = matches!(recorded, Some(Stamp::Present { hash: Some(_), .. })) || modified + MTIME_GRANULARITY >= now;
86	    let hash = if hashed {
87	        match content_hash(path, meta.is_dir()) {
88	            Some(hash) => Some(hash),
89	            None => return Stamp::Unknown,
90	        }
91	    } else {
92	        None
93	    };
94	    Stamp::Present { modified, len: meta.len(), hash }
95	}
