97	fn content_hash(path: &Utf8Path, is_dir: bool) -> Option<u64> {
98	    let mut hasher = rustc_hash::FxHasher::default();
99	    if is_dir {
100	        let mut names: Vec<String> =
101	            path.read_dir_utf8().ok()?.flatten().map(|entry| entry.file_name().to_owned()).collect();
102	        names.sort();
103	        names.hash(&mut hasher);
104	    } else {
105	        std::fs::read(path).ok()?.hash(&mut hasher);
106	    }
