20	/// The fixture project in a scratch directory whose name has an upper-case letter (see `replay_tsc.rs`), with
21	/// `replay-tsc` installed as `node_modules/typescript/bin/tsc` when `with_tsc`.
22	fn project(with_tsc: bool) -> Project {
23	    let dir = tempfile::Builder::new().prefix("Replay").tempdir().unwrap();
24	    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
