const root = '/Users/gabe/Projects/caliper-fixtures/s6/probe-proj'
const E = `${root}/src/E.tsx`, X = `${root}/src/extra.ts`
const client = new Client({ tsserverPath: process.argv[2], cwd: root })
await client.connect()
const call = (m, p) => client.apiRequest(m, p)
await call('initialize', null)
const options = (await call('parseConfigFile', { file: `${root}/tsconfig.json` })).options
const writeE = n => writeFileSync(E, `import type { ButtonProps } from '@chakra-ui/react'\nimport type { Extra } from './extra'\nexport function E(props: ButtonProps & Extra & { edit${n}: string }) { return null }\n`)
const writeX = n => writeFileSync(X, `export interface Extra { extra${n}: string }\n`)
async function props(snapshot, project) {
  const sc = { snapshot, project }
  const mod = await call('getSymbolOfSourceFile', { ...sc, file: E })
  const exports = await call('getExportsOfModule', { ...sc, symbol: mod.reference })
  const e = exports.find(s => s.name === 'E')
  const ty = await call('getTypeOfSymbol', { ...sc, symbol: e.reference })
  const [sig] = await call('getSignaturesOfType', { ...sc, type: ty.id, kind: 0 })
  const [param] = await call('getParametersOfSignature', { ...sc, objectId: sig.id })
  const pty = await call('getTypeOfSymbol', { ...sc, symbol: param.reference })
  return (await call('getPropertiesOfType', { ...sc, type: pty.id })).map(p => p.name).filter(n => /^(edit|extra)\d/.test(n)).join(',')
}
