// nothing changed on disk since: notify E again
const u2 = await call('updateSnapshot', { snapshot: u.snapshot, changes: { fileNotifications: { changed: [E] }, ensurePrograms: true } })
console.log('(c) notify E, unchanged content: same id', u2.snapshot === u.snapshot, 'changes', JSON.stringify(u2.changes))
