for (let n = 300; n < 340; n++) {
  writeE(n)
  st = performance.now()
  const next = await call('updateSnapshot', { snapshot: base.snapshot, changes: { fileNotifications: { changed: [E] }, ensurePrograms: true } })
  up.push(performance.now() - st)
