  if (!got.includes(`edit${n}`)) console.log('STALE', n, got)
}
up.sort((a, b) => a - b)
console.log('(f) update with ensure, 40 edits: p50', up[20].toFixed(1), 'p95', up[38].toFixed(1), 'max', up[39].toFixed(1))
