use std::time::Instant;

fn main() {
    let names: Vec<String> = std::fs::read_to_string(std::env::args().nth(1).unwrap())
        .unwrap()
        .lines()
        .map(str::to_string)
        .collect();
    for _ in 0..3 {
        let started = Instant::now();
        let mut total = 0u64;
        for name in &names {
            total += std::fs::metadata(name).map(|m| m.len()).unwrap_or(0);
        }
        println!("sequential {} files: {:?} ({total})", names.len(), started.elapsed());
    }
    for threads in [4, 8] {
        let started = Instant::now();
        let chunk = names.len().div_ceil(threads);
        let total: u64 = std::thread::scope(|scope| {
            let handles: Vec<_> = names
                .chunks(chunk)
                .map(|part| scope.spawn(move || part.iter().map(|n| std::fs::metadata(n).map(|m| m.len()).unwrap_or(0)).sum::<u64>()))
                .collect();
            handles.into_iter().map(|h| h.join().unwrap()).sum()
        });
        println!("{threads} threads: {:?} ({total})", started.elapsed());
    }
}

